-- Первые 30 учеников из годового отчёта 2025–2026. Повторный запуск не создаёт дубли.
insert into public.students(full_name,active)
select n,true from unnest(array[
  'Ихсан Талгатович','Салих Талгатович','Рустам Ильфатович','Исмаил Ринатович','Хаким Алиевич','Нурислам Алиевич','Исмагыйль Алиевич','Ибрахим Ильшатович','Исмагыйл Ильшатович','Сулейман Ильшатович','Мухаммад Ильшатович','Хасан Динарович','Мухаммад Динарович','Шамсимухаммад Линарович','Мухаммад Эльдарович','АбдульКарим Ринатович','Мухаммад Рашидович','Ибрахим Рашидович','Ахмад Айратович','Абдуррауф Саидович','Алан Тимурович','Мустафа Рушанович','Ахмад Рушанович','Умар Аббасович','АбдуЛла Аббасович','Идрис Ильдарович','Ильяс Ильдарович','Аяз Алмазович','Риназ Алмазович','Ильяс Алмазович'
]) as n
where not exists(select 1 from public.students s where lower(trim(s.full_name))=lower(trim(n)));
